/** 100.00 split equally among `n` in order: each share rounded half to even to two decimals, the remainder (100.00
 *  minus the shares added up) given to the first. */
export function equalShares(n: number): string[] {
  if (n === 0) return [];
  const N = BigInt(n);
  const q = 10000n / N;
  const rem = 10000n % N;
